#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/mman.h>
#include <errno.h>

#define BUFFER_SIZE 256
#define MAX_HEADER_LEN 512

struct request_context {
    char method[16];
    char path[BUFFER_SIZE];
    char host[128];
    char user_agent[BUFFER_SIZE];
    int content_length;
    char body[BUFFER_SIZE];
};

// Legacy parsing function from original monolith (circa 2009)
// Known issue: no bounds checking on X-Forwarded-For concatenation
void parse_forwarded_headers(char *raw_headers, struct request_context *ctx) {
    char forwarded_chain[BUFFER_SIZE];
    char *line = strtok(raw_headers, "\r\n");

    memset(forwarded_chain, 0, BUFFER_SIZE);

    while (line != NULL) {
        if (strncasecmp(line, "X-Forwarded-For:", 16) == 0) {
            // BUG: strcpy with no length check - multiple XFF headers
            // get concatenated into fixed-size buffer
            if (strlen(forwarded_chain) > 0) {
                strcat(forwarded_chain, ", ");
            }
            strcat(forwarded_chain, line + 17);
        }
        line = strtok(NULL, "\r\n");
    }

    // Overflow here can overwrite ctx->body and beyond
    memcpy(ctx->body, forwarded_chain, strlen(forwarded_chain));
}

void handle_connection(int client_fd) {
    char recv_buffer[2048];
    struct request_context ctx;
    int bytes_read;

    memset(&ctx, 0, sizeof(ctx));
    bytes_read = read(client_fd, recv_buffer, sizeof(recv_buffer) - 1);

    if (bytes_read <= 0) return;
    recv_buffer[bytes_read] = '\0';

    // Parse the first line
    sscanf(recv_buffer, "%15s %255s", ctx.method, ctx.path);

    // Parse headers (vulnerable path)
    parse_forwarded_headers(recv_buffer, &ctx);

    // Process request...
    char response[] = "HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nOK";
    write(client_fd, response, strlen(response));
}

int main(int argc, char *argv[]) {
    int server_fd, client_fd;
    struct sockaddr_in addr;
    int port = 8080;

    if (argc > 1) port = atoi(argv[1]);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) { perror("socket"); exit(1); }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);

    if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("bind"); exit(1);
    }

    listen(server_fd, 128);
    printf("Legacy monolith listening on port %d\n", port);

    while (1) {
        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) continue;
        handle_connection(client_fd);
        close(client_fd);
    }

    return 0;
}
